  UniTask.DelayFrame(1, "Update", nil, false)
  local lineCount = self.honbunView:GetTextInfo(self.honbunView.text).lineCount
  local y = ((function() if (playing.color == "White") then return (30 * lineCount) else return 10 end end)())
  self:GetComponent("RectTransform").sizeDelta = NEW("Vector2", nil, 380, y)
