  elseif playing.henji ~= "" or (self._live.isOiwai and Random.Range(0, 3) < 2) then
    local num = Random.Range(0, self._superchats.Length)
    self.bgDefault = IDX(self._superchats, num).Color
    self._baseImage.color = self.bgDefault
    self:SuperChatEffect()
    self.gameObject:GetComponent("Button"):OnClickAsObservable():Subscribe(function(_)
      self:hirou(self.playing)
    end):AddTo(self.gameObject)
  else
