      self:sakujo(self.playing)
    end):AddTo(self.gameObject)
  end
end

function C:hirou(playing)
  if self._live:isActiveReaction() and not self.isHiroizumi then
    self.isHiroizumi = true
    self._live.NowPlaying.isGensoku.Value = false
    self:AdjustSpeed()
    self._live:hirowareta(playing)
    self._live:Actioned()
  end
end

function C:sakujo(playing)
  if self._live:isActiveReaction() and not self.isHiroizumi and (not EventManager.isHorror or StatusManager:GetStatus("DayIndex") ~= 29) then
    self.isHiroizumi = true
    self._live.NowPlaying.isGensoku.Value = false
    self:AdjustSpeed()
    AudioManager:PlaySeByType("SE_pien", false)
    self.honbunView:DOColor(NEW("Color", nil, 0, 0, 0, 0), 0.4):Play()
    self.isDeleted = true
    if playing.delta ~= 0 and playing.diffStatusType ~= "Tension" then
      spawn(function() StatusManager:UpdateStatus(playing.diffStatusType, playing.delta) end)
    end
    self._live:Actioned()
  end
end

function C:highlighted()
  if not self._live:isActiveReaction() or self.isHiroizumi then
    return
  end
  if EventManager.isHorror and StatusManager:GetStatus("DayIndex") == 29 then
    if Settings.CurrentLanguage.Value ~= "EN" then
      local uTF = Encoding.UTF8
      local encoding = Encoding.GetEncoding("Shift_JIS")
      local bytes = uTF:GetBytes(self.honbun)
      local text = encoding:GetString(bytes)
      self.honbunView.text = text
    else
      self.honbunView.text = "縺溘☆縺代※"
    end
  else
    self._live.NowPlaying.isGensoku.Value = true
    self:AdjustSpeed()
    if self.playing.henji ~= "" then
      self._baseImage.color = NEW("Color", nil, 0.98039216, 1, 0.5529412, 1)
    else
      self.Scull:SetActive(true)
    end
  end
end

function C:AdjustSpeed()
  if self._live.NowPlaying.isGensoku.Value then
    self._live.NowPlaying.BASESPEED = 3500
  else
    self._live.NowPlaying.BASESPEED = self._live.NowPlaying.STARTSPEED
  end
end

function C:exited()
  CursorManager:SetCursor(nil, Vector2.zero, "Auto")
  self._live.NowPlaying.isGensoku.Value = false
  self:AdjustSpeed()
  self._baseImage.color = self.bgDefault
  self.Scull:SetActive(false)
  local _ = self.isHiroizumi
end

function C:Select()
  self._live.SelectingComment = self
end

function C:Deselect()
  if self._live.SelectingComment == self then
    self._live.SelectingComment = nil
  end
end

